SourceCode.Declaration:
/// <summary>
/// Result contract for rollback-only, resident X++ interpreter execution.
/// Timings are measured inside AOS and expressed in microseconds.
/// </summary>
[DataContract]
public final class MXTXppInterpreterExecutionResponse
{
    boolean success;
    boolean rolledBack;
    str requestId;
    str output;
    str error;
    int instructionCount;
    int64 parseMicroseconds;
    int64 compileMicroseconds;
    int64 executeMicroseconds;
    int64 totalMicroseconds;
    str moduleName;
    int moduleVersion;
    boolean cacheHit;
}

Method.Source:
